import { HttpMailClient } from './mail.js'
import { config } from './config.js'

interface Report { subject: string; body: string }

export class ReportService {
  async send(report: Report): Promise<void> {
    const client = new HttpMailClient(config.smtpUrl)
    await client.deliver(report.subject, report.body)
  }
}

import { createConnection } from './db.js'
import { config } from './config.js'

interface Order { id: string; total: number }

export const listOrders = async (customerId: string): Promise<Order[]> => {
  const db = createConnection(config.databaseUrl)
  const rows = await db.query('select id, total from orders where customer_id = $1', [customerId])
  return rows.map((row) => ({ id: row.id, total: Number(row.total) }))
}

import axios from 'axios'

interface Weather { tempC: number }

export const fetchWeather = async (city: string): Promise<Weather> => {
  const http = axios.create({ baseURL: 'https://weather.example.com', timeout: 2000 })
  const response = await http.get(`/current/${city}`)
  return { tempC: response.data.temp_c }
}

import { RedisCache } from './cache.js'

export class ProfileLookup {
  #cache: RedisCache | undefined

  async find(userId: string): Promise<string | null> {
    this.#cache ??= new RedisCache('redis://localhost:6379')
    return this.#cache.get(`profile:${userId}`)
  }
}

import { PostgresPetRepository } from './petRepository.js'
import { pool } from './pool.js'

interface Pet { name: string }

export class PetService {
  readonly #repository: PostgresPetRepository

  constructor() {
    this.#repository = new PostgresPetRepository(pool)
  }

  findByName(name: string): Promise<Pet | null> {
    return this.#repository.findByName(name)
  }
}

interface Invoice { id: string; amountCents: number }

export const chargeInvoice = async (invoice: Invoice): Promise<string> => {
  const { StripeClient } = await import('./stripe.js')
  const stripe = new StripeClient(process.env['STRIPE_KEY'] ?? '')
  const charge = await stripe.charge(invoice.amountCents)
  return charge.id
}

import { createLogger } from './logging.js'

interface Job { id: string }

export const runJob = async (job: Job): Promise<void> => {
  const log = createLogger({ job: job.id })
  log.info('starting')
  await new Promise((resolve) => setTimeout(resolve, 10))
  log.info('finished')
}

export const withTimeout = <T>(work: (signal: AbortSignal) => Promise<T>, ms: number): Promise<T> => {
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), ms)
  return new Promise<T>((resolve, reject) => {
    work(controller.signal).then(resolve, reject).finally(() => clearTimeout(timer))
  })
}

import type { MailClient } from './mail.js'

interface Report { subject: string; body: string }

export class ReportService {
  readonly #mail: MailClient

  constructor(mail: MailClient) {
    this.#mail = mail
  }

  async send(report: Report): Promise<void> {
    const envelope = new Map([['subject', report.subject], ['body', report.body]])
    await this.#mail.deliver(Object.fromEntries(envelope))
  }
}

interface Event { name: string; at: Date }

export const summarise = (events: Event[]): Map<string, number> => {
  const counts = new Map<string, number>()
  const cutoff = new Date(Date.now() - 86_400_000)
  for (const event of events) {
    if (event.at < cutoff) continue
    counts.set(event.name, (counts.get(event.name) ?? 0) + 1)
  }
  if (counts.size === 0) throw new Error('no recent events')
  return counts
}

import { Money } from './money.js'

interface LineItem { unitCents: number; quantity: number }

export const total = (items: LineItem[]): Money => {
  let sum = new Money(0, 'USD')
  for (const item of items) {
    sum = sum.plus(new Money(item.unitCents * item.quantity, 'USD'))
  }
  return sum
}

export const parseCallback = (raw: string): { host: string; code: string | null } => {
  const url = new URL(raw)
  const bytes = new TextEncoder().encode(url.pathname)
  const code = bytes.length > 0 ? url.searchParams.get('code') : null
  return { host: url.host, code }
}
